INSERT INTO `settings` (`id`, `key`, `value`, `group`, `type`, `created_at`, `updated_at`) VALUES
(60, 'hero_video_url', NULL, 'homepage', 'url', NULL, NULL),
(61, 'hero_video_file', NULL, 'homepage', 'file', NULL, NULL),
(62, 'hero_headline', 'KAMI BUKA<br/><span class="gold-shimmer">SETIAP HARI</span>', 'homepage', 'text', NULL, NULL),
(63, 'hero_headline_en', 'WE ARE<br/><span class="gold-shimmer">OPEN DAILY</span>', 'homepage', 'text', NULL, NULL),
(64, 'hero_subheadline', 'Setiap Hari: 09.00 - 18.00 WITA', 'homepage', 'text', NULL, NULL),
(65, 'hero_subheadline_en', 'Daily: 09:00 AM - 6:00 PM WITA', 'homepage', 'text', NULL, NULL),
(66, 'hero_description', 'Aquaboom Waterpark Balikpapan — Pengalaman rekreasi air yang unik di 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan. Managed by Astara Hotel Balikpapan.', 'homepage', 'text', NULL, NULL),
(67, 'hero_description_en', 'Aquaboom Waterpark Balikpapan — A unique waterpark experience on 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan. Managed by Astara Hotel Balikpapan.', 'homepage', 'text', NULL, NULL),
(68, 'philosophy_text', 'Aquaboom Waterpark Balikpapan menghadirkan pengalaman rekreasi air urban yang unik di Balikpapan. Berlokasi strategis di pusat kota Balikpapan (BSB Area), kami menawarkan keceriaan wahana air premium di 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan.', 'about', 'text', NULL, NULL),
(69, 'philosophy_text_en', 'Aquaboom Waterpark Balikpapan brings a unique urban water recreation experience in Balikpapan. Strategically located in the heart of Balikpapan (BSB Area), we offer the joy of premium water slides on 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan.', 'about', 'text', NULL, NULL),
(70, 'philosophy_video_url', NULL, 'about', 'file', NULL, NULL),
(71, 'philosophy_video_file', NULL, 'about', 'file', NULL, NULL),
(72, 'mission_text', 'Terletak di Lantai 7 (Shared Common Area Astara Hotel & Pentacity Hotel Balikpapan) - Balikpapan Superblock, Aquaboom menghadirkan standar baru rekreasi air perkotaan di Balikpapan. Kami menggabungkan keseruan bermain air berkelas dengan aksesibilitas dan kenyamanan modern.', 'about', 'text', NULL, NULL),
(73, 'mission_text_en', 'Located on the 7th Floor (Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan) - Balikpapan Superblock, Aquaboom presents a new standard of urban water recreation in Balikpapan. We combine the excitement of high-class water play with accessibility and modern comfort.', 'about', 'text', NULL, NULL);
INSERT INTO `wahanas` (`id`, `name`, `description`, `image_url`, `order_column`, `created_at`, `updated_at`, `created_by`, `updated_by`, `deleted_at`, `thrill_level`, `name_en`, `description_en`) VALUES
(13, 'Giant Bucket Playground', 'Area bermain air interaktif utama dengan ember tumpah raksasa dan berbagai seluncuran seru.', 'https://aquaboombsb.com/wp-content/uploads/2023/12/V1.jpg', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Giant Bucket Playground', 'Main interactive water play area with a giant spilling bucket and various exciting slides.'),
(14, 'Splash & Leisure Pool', 'Nikmati sensasi berenang santai yang menyenangkan di 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan dengan pemandangan kota Balikpapan.', 'https://aquaboombsb.com/wp-content/uploads/2023/12/V2.jpg', 2, NULL, NULL, NULL, NULL, NULL, NULL, 'Splash & Leisure Pool', 'Enjoy the sensation of relaxing swimming on 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan with Balikpapan city views.'),
(15, 'Family Water Playground', 'Wahana permainan air keluarga yang aman dan menyenangkan untuk anak-anak hingga dewasa.', 'https://aquaboombsb.com/wp-content/uploads/2023/12/V3.jpg', 3, NULL, NULL, NULL, NULL, NULL, NULL, 'Family Water Playground', 'Safe and fun family water play ride for children to adults.');
INSERT INTO `ticket_packages` (`id`, `name`, `description`, `price`, `discount_price`, `type`, `is_active`, `created_at`, `updated_at`, `created_by`, `updated_by`, `discount_type`, `deleted_at`, `validity_type`, `valid_dates`, `valid_days`, `terms_and_conditions`, `name_en`, `description_en`, `terms_and_conditions_en`, `image_url`, `inquiry_type`, `inquiry_custom_link`, `sales_start`, `sales_end`, `is_featured_home`, `sort_order`, `banner_image`, `holiday_ids`, `include_national_holidays`, `include_peak_season`) VALUES
(33, 'Tiket Regular Weekdays', 'Tiket masuk harian untuk hari Senin sampai Jumat. Jam operasional: 09:00 - 18:00 WITA.', '95000.00', NULL, 'regular', 1, NULL, NULL, NULL, NULL, 'amount', NULL, 'weekday', NULL, NULL, NULL, 'Regular Weekday Ticket', 'Daily entry ticket valid from Monday to Friday. Operational hours: 09:00 - 18:00 WITA.', NULL, 'https://picsum.photos/600/400?random=60', 'none', NULL, NULL, NULL, 0, 0, NULL, NULL, 1, 0),
(34, 'Tiket Regular Weekend', 'Tiket masuk harian untuk hari Sabtu, Minggu, dan Libur Nasional. Jam operasional: 09:00 - 18:00 WITA.', '125000.00', NULL, 'regular', 1, NULL, NULL, NULL, NULL, 'amount', NULL, 'weekend', NULL, NULL, NULL, 'Regular Weekend Ticket', 'Daily entry ticket valid on Saturday, Sunday, and National Holidays. Operational hours: 09:00 - 18:00 WITA.', NULL, 'https://picsum.photos/600/400?random=61', 'none', NULL, NULL, NULL, 0, 0, NULL, NULL, 1, 0),
(35, 'Duo Pass', 'Tiket masuk untuk 2 orang + 2 handuk + 1 locker standar gratis + 30 menit foot massage masing-masing. Hemat hingga 15%!', '320000.00', '270000.00', 'bundle', 1, NULL, NULL, NULL, NULL, 'amount', NULL, 'all_days', NULL, NULL, NULL, 'Duo Pass', 'Entry ticket for 2 people + 2 pool towels + 1 locker standard + 30 mins foot massage each. Save up to 15%!', NULL, 'https://picsum.photos/600/400?random=51', 'none', NULL, NULL, NULL, 0, 0, NULL, NULL, 1, 0),
(36, 'Four Pack Pass', 'Tiket masuk untuk 4 orang (dewasa/anak) + 4 handuk kolam gratis + 1 family locker + Voucher makanan Rp 100.000 + 10% off spa treatment per orang. Hemat hingga 25%!', '600000.00', '450000.00', 'bundle', 1, NULL, NULL, NULL, NULL, 'amount', NULL, 'all_days', NULL, NULL, NULL, 'Four Pack Pass', 'Entry ticket for 4 people + 4 pool towels + 1 family locker + Food Voucher Rp 100.000 + 10% off spa treatment per person. Save up to 25%!', NULL, 'https://picsum.photos/600/400?random=52', 'none', NULL, NULL, NULL, 0, 0, NULL, NULL, 1, 0),
(37, 'Birthday Package', '10 tiket masuk + gazebo + dekorasi ulang tahun + kue ulang tahun + 10 minuman non-alkohol + special gift dari Aquaboom + voucher Rp 200.000 in-park.', '1800000.00', NULL, 'bundle', 1, NULL, NULL, NULL, NULL, 'amount', NULL, 'all_days', NULL, NULL, NULL, 'Birthday Package', '10 entry tickets + gazebo + birthday decoration + birthday cake + 10 non-alcoholic drinks + special gift + Rp 200.000 in-park credit.', NULL, 'https://picsum.photos/600/400?random=53', 'whatsapp', NULL, NULL, NULL, 0, 0, NULL, NULL, 1, 0),
(38, 'Unlimited Annual Pass', 'Akses tak terbatas selama 12 bulan penuh + 1 handuk gratis per kunjungan + 20% off untuk tambahan 4 teman per kunjungan + 10% off gazebo, locker & merchandise. Dewasa: Rp 780.000, Anak (2-11 th): Rp 660.000.', '780000.00', NULL, 'bundle', 1, NULL, NULL, NULL, NULL, 'amount', NULL, 'all_days', NULL, NULL, NULL, 'Unlimited Annual Pass', 'Unlimited 12-month access + 1 free towel per visit + 20% off for up to 4 friends per visit + 10% off gazebo, locker & merchandise. Adult: Rp 780,000, Child: Rp 660,000.', NULL, 'https://picsum.photos/600/400?random=54', 'whatsapp', NULL, NULL, NULL, 0, 0, NULL, NULL, 1, 0),
(39, 'Return Day Pass', 'Hemat lebih dari 15% untuk kunjungan kedua Anda dalam 7 hari! Hanya bisa dibeli di loket dalam taman. Dewasa: Rp 63.000, Anak (2-11 th): Rp 50.000.', '63000.00', NULL, 'bundle', 1, NULL, NULL, NULL, NULL, 'amount', NULL, 'all_days', NULL, NULL, NULL, 'Return Day Pass', 'Save over 15% on your second visit within 7 days! Only available for purchase inside the park. Adult: Rp 63,000, Child: Rp 50,000.', NULL, 'https://picsum.photos/600/400?random=55', 'none', NULL, NULL, NULL, 0, 0, NULL, NULL, 1, 0),
(40, 'Custom Group Package', 'Paket rombongan perusahaan, gathering tim, atau kunjungan sekolah/keluarga besar di atas 20 orang. Bisa kustom makanan, area eksklusif, & dedicated event coordinator.', '0.00', NULL, 'bundle', 1, NULL, NULL, NULL, NULL, 'amount', NULL, 'all_days', NULL, NULL, NULL, 'Custom Group Package', 'Corporate gatherings, team events, or school/family trips of 20+ people. Custom meals, exclusive area reservations, & dedicated event coordinator available.', NULL, 'https://picsum.photos/600/400?random=56', 'whatsapp', NULL, NULL, NULL, 0, 0, NULL, NULL, 1, 0);
INSERT INTO `add_ons` (`id`, `name`, `description`, `price`, `image`, `is_active`, `created_at`, `updated_at`, `deleted_at`, `name_en`, `description_en`, `sort_order`) VALUES
(17, 'Sewa Gazebo Standard', 'Gazebo nyaman kapasitas 4-6 orang untuk bersantai bersama keluarga, include stopkontak dan matras empuk.', '150000.00', 'assets/img/aquaboom.jpeg', 1, NULL, NULL, NULL, 'Standard Gazebo Rental', 'Comfortable private gazebo for 4-6 guests to relax with family, includes power outlet and soft cushioned mat.', 0),
(18, 'Single Tube (Ban Single)', 'Sewa ban renang single untuk meluncur lebih cepat dan nyaman di wahana seluncuran.', '30000.00', 'assets/img/aquaboom.jpeg', 1, NULL, NULL, NULL, 'Single Tube Rental', 'Single inflatable swim tube rental for faster, smoother, and more comfortable rides on the water slides.', 0),
(19, 'Double Tube (Ban Double)', 'Sewa ban renang double untuk meluncur berpasangan bersama teman atau keluarga.', '50000.00', 'assets/img/aquaboom.jpeg', 1, NULL, NULL, NULL, 'Double Tube Rental', 'Tandem double swim tube rental to slide together with a partner, friend, or family member.', 0),
(20, 'Loker Premium', 'Sewa loker ukuran besar dengan pengaman kunci digital RFID untuk kenyamanan barang bawaan Anda.', '25000.00', 'assets/img/aquaboom.jpeg', 1, NULL, NULL, NULL, 'Premium Locker Rental', 'Large-capacity secure locker with digital RFID keycard lock for maximum peace of mind regarding your belongings.', 0);
INSERT INTO `facilities` (`id`, `name`, `type`, `description`, `features`, `image_url`, `is_active`, `created_at`, `updated_at`, `name_en`, `description_en`, `features_en`, `menu_items`, `sort_order`) VALUES
(25, 'Oasis Food Court', 'dining', 'Tempat menikmati aneka makanan ringan favorit, hidangan lezat khas lokal, dan minuman segar setelah bermain air.', '["Menu variatif","Minuman dingin segar","Area bersih nyaman"]', 'https://aquaboombsb.com/wp-content/uploads/2023/12/fasilitas.png', 1, NULL, NULL, 'Oasis Food Court', 'A place to enjoy various favorite snacks, delicious local dishes, and fresh drinks after playing in the water.', '["Varied menu","Fresh cold drinks","Clean & comfortable area"]', '["dining-menus\\/01M1BCTTDQWETSW9NMWYF62QYN.webp"]', 0),
(26, 'GAZEBO PRIBADI & CABANA', 'gazebo', 'Tingkatkan kenyamanan kunjungan Anda dengan menyewa Gazebo pribadi. Terletak di area teduh nan asri, lengkap dengan layanan pesan antar makanan, pengisian daya, dan privasi penuh.', '["Layanan makanan & minuman langsung ke gazebo","Privasi & kenyamanan maksimal","Kapasitas 4\\u20138 orang per gazebo"]', 'https://picsum.photos/600/400?random=40', 1, NULL, NULL, 'PRIVATE GAZEBO & CABANA', 'Enhance your visit comfort by renting a private Gazebo. Located in a shady, lush area, complete with food delivery service, charging outlets, and full privacy.', '["Food & beverage service directly to the gazebo","Maximum privacy & comfort","Capacity of 4\\u20138 people per gazebo"]', NULL, 0),
(27, 'PENYEWAAN LOKER & HANDUK', 'general', 'Nikmati petualangan air tanpa rasa cemas. Kami menyediakan fasilitas loker otomatis dengan keamanan terintegrasi, serta penyewaan handuk bersih yang selalu disterilkan secara berkala.', '["Sistem kunci loker menggunakan gelang RFID \\/ pin","Handuk premium bersih & higienis","Lokasi loker strategis dekat ruang bilas"]', 'https://picsum.photos/600/400?random=42', 1, NULL, NULL, 'LOCKER & TOWEL RENTAL', 'Enjoy water adventures without worries. We provide automated locker facilities with integrated security, and clean towels sterilized regularly.', '["Locker locking system using RFID wristband \\/ pin","Premium, clean & hygienic towels","Strategic locker locations near the shower rooms"]', NULL, 0),
(28, 'RUANG BILAS & RUANG GANTI', 'general', 'Ruang bilas dan ruang ganti premium kami dirancang dengan mengutamakan kebersihan dan kenyamanan. Dilengkapi dengan pancuran air hangat, bilik ganti pribadi yang luas, serta pengering rambut.', '["Bilik shower pribadi dengan air hangat","Peralatan mandi lengkap (sabun & sampo cair)","Wastafel dan cermin rias berukuran besar"]', 'https://picsum.photos/600/400?random=44', 1, NULL, NULL, 'SHOWER & CHANGING ROOMS', 'Our premium shower and changing rooms are designed with hygiene and comfort in mind. Equipped with hot showers, spacious private changing stalls, and hair dryers.', '["Private shower stalls with hot water","Complete toiletries (liquid soap & shampoo)","Large washbasin and vanity mirrors"]', NULL, 0),
(29, 'KLINIK PERTOLONGAN PERTAMA (P3K)', 'general', 'Keselamatan Anda adalah prioritas utama kami. Klinik P3K Aquaboom dilengkapi dengan peralatan medis darurat standar internasional serta dipandu oleh tim medis terlatih yang bersertifikasi.', '["Perawat dan pertolongan medis siaga selama jam operasional","Obat-obatan umum dan peralatan bantuan darurat lengkap","Akses jalur evakuasi darurat yang cepat"]', 'https://picsum.photos/600/400?random=46', 1, NULL, NULL, 'FIRST AID CLINIC', 'Your safety is our top priority. Aquaboom\'s First Aid Clinic is equipped with standard international emergency medical supplies and guided by certified trained medical staff.', '["Nurses and medical assistance standby during operating hours","General medicines and complete emergency aid equipment","Fast emergency evacuation access route"]', NULL, 0),
(30, 'MUSHOLA', 'general', 'Kami menyediakan ruang ibadah (Mushola) yang tenang, sejuk, dan bersih untuk menunjang kenyamanan ibadah Anda. Terpisah secara higienis antara area wudhu pria dan wanita.', '["Tempat wudhu bersih terpisah gender","Dilengkapi sajadah, mukena, sarung, dan Al-Quran","Ruangan ber-AC yang nyaman"]', 'https://picsum.photos/600/400?random=48', 1, NULL, NULL, 'PRAYER ROOM (MUSHOLA)', 'We provide a quiet, cool, and clean prayer room (Mushola) for your worship comfort. Hygienically separated ablution areas for men and women.', '["Clean gender-segregated ablution areas","Equipped with prayer mats, female prayer robes, sarongs, and Al-Quran","Comfortable air-conditioned room"]', NULL, 0);
INSERT INTO `faqs` (`id`, `question`, `answer`, `is_active`, `sort_order`, `created_at`, `updated_at`, `question_en`, `answer_en`) VALUES
(34, 'Jam berapa jam operasional Aquaboom?', 'Kami buka setiap hari (Senin — Minggu & Libur Nasional) mulai pukul 09:00 WITA - 18:00 WITA (Batas masuk terakhir pukul 17:00 WITA).', 1, 1, NULL, NULL, 'What are the operational hours of Aquaboom?', 'We are open daily (Monday — Sunday & Public Holidays) from 09:00 WITA - 18:00 WITA (Last admission at 17:00 WITA).'),
(35, 'Bagaimana ketentuan pakaian renang?', 'Demi kenyamanan dan keselamatan, pengunjung disarankan menggunakan pakaian renang yang nyaman. Pakaian dengan kancing besi menonjol atau ritsleting tajam dilarang di seluncuran besar.', 1, 2, NULL, NULL, 'What is the swimming attire policy?', 'For comfort and safety, guests are advised to wear proper swimwear. Attire with protruding metal buttons or sharp zippers is prohibited on large slides.'),
(36, 'Apakah boleh membawa makanan dan minuman dari luar?', 'Makanan dan minuman dari luar tidak diperkenankan dibawa masuk ke area waterpark untuk menjaga kebersihan dan higienitas area kolam.', 1, 3, NULL, NULL, 'Can we bring outside food and drinks?', 'Outside food and beverages are not allowed inside the waterpark area to maintain the hygiene and cleanliness of the pool area.'),
(37, 'Apakah tersedia penyewaan loker dan handuk?', 'Ya, kami menyediakan fasilitas penyewaan loker penyimpanan barang berharga serta penyewaan handuk bersih untuk kenyamanan kunjungan Anda.', 1, 4, NULL, NULL, 'Are towel and locker rentals available?', 'Yes, we provide locker rentals for securing valuables as well as clean towel rentals for your convenience.');
INSERT INTO `home_page_cards` (`id`, `title`, `description`, `image_url`, `link`, `link_text`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Pilih Tiket Masuk', 'Beli tiket masuk lebih mudah secara online melalui website kami untuk menikmati keseruan tak terbatas.', 'https://aquaboombsb.com/wp-content/uploads/2023/12/Tiket.png', '/ticket', 'Pesan Tiket', 1, 1, NULL, NULL),
(3, 'Petunjuk Arah & Lokasi', 'Berlokasi strategis di Lantai 7 Astara Hotel, kawasan Balikpapan Super Block (BSB), Jl. Jenderal Sudirman No. 47.', 'https://aquaboombsb.com/wp-content/uploads/2023/12/V2.jpg', '/about#lokasi', 'Lihat Lokasi', 1, 3, NULL, NULL),
(4, 'Fasilitas Lengkap', 'Nikmati kenyamanan fasilitas hotel bintang 4, Musholla, Kamar Bilas bersih, Toilet, hingga Gazebo nyaman untuk bersantai.', 'https://aquaboombsb.com/wp-content/uploads/2023/12/fasilitas.png', '/facilities', 'Lihat Fasilitas', 1, 4, NULL, NULL),
(5, 'Tanya Jawab (FAQ)', 'Dapatkan jawaban lengkap mengenai ketentuan pakaian renang, penyimpanan loker, makanan, dan persyaratan lainnya.', 'https://aquaboombsb.com/wp-content/uploads/2023/12/funfact.png', '/faq', 'Lihat FAQ', 1, 5, NULL, NULL),
(2, 'Tentang Kami', 'Aquaboom Waterpark Balikpapan — Waterpark ikonik di Balikpapan yang menghadirkan keseruan rekreasi air premium di 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan.', 'https://aquaboombsb.com/wp-content/uploads/2023/12/V1.jpg', '/about', 'Baca Selengkapnya', 1, 2, NULL, NULL);
