(4, 'App\\Models\\TicketPackage', 2, 'updated', '{"id":2,"name":"Regular ","description":"adasdasd","price":"120000.00","discount_price":"20000.00","type":"regular","is_active":true,"created_by":null,"updated_by":2,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null}', '{"validity_type":"weekday"}', 2, '2026-07-22 08:02:10', '2026-07-22 08:02:10'),
(5, 'App\\Models\\TicketPackage', 2, 'updated', '{"id":2,"name":"Regular ","description":"adasdasd","price":"120000.00","discount_price":"20000.00","type":"regular","is_active":true,"created_by":null,"updated_by":2,"discount_type":"amount","deleted_at":null,"validity_type":"weekday","valid_dates":null,"valid_days":null,"terms_and_conditions":null}', '{"terms_and_conditions":"<ul><li><strong>Masa Berluku Tiket:<\\/strong> Tiket hanya berlaku untuk 1 (satu) orang pada tanggal dan sesi kunjungan yang telah dipilih saat transaksi.<\\/li><li><strong>Prosedur Masuk:<\\/strong> Pengunjung wajib menunjukkan <em>QR Code<\\/em> atau E-tiket dari ponsel di loket masuk untuk dipindai (<em>scan<\\/em>) oleh petugas.<\\/li><li><strong>Kebijakan Pembatalan &amp; Refund:<\\/strong> Tiket yang sudah dibeli bersifat <strong>Non-Refundable<\\/strong> (tidak dapat dikembalikan uangnya) dengan alasan apa pun dari pihak pembeli.<\\/li><li><strong>Aturan Perubahan Jadwal (<\\/strong><strong><em>Reschedule<\\/em><\\/strong><strong>):<\\/strong> Pengajuan <em>reschedule<\\/em> tanggal kunjungan dapat dilakukan maksimal H-1 sebelum tanggal kedatangan, selama kuota harian masih tersedia.<\\/li><li><strong>Ketentuan Cuaca Buruk (<\\/strong><strong><em>Force Majeure<\\/em><\\/strong><strong>):<\\/strong> Apabila operasional dihentikan sementara demi keselamatan akibat cuaca ekstrem (petir\\/badai), tiket yang sudah digunakan tidak dapat di-refund, melainkan akan diberikan hak <em>reschedule<\\/em>.<\\/li><li><strong>Tata Tertib &amp; Keselamatan:<\\/strong> Pengunjung wajib menggunakan pakaian renang yang sesuai, mendampingi anak-anak, dan mematuhi seluruh imbauan penjaga kolam (<em>lifeguard<\\/em>).<\\/li><li><strong>Larangan:<\\/strong> Dilarang membawa makanan dan minuman dari luar area kolam, barang berbahaya, obat-obatan terlarang, serta hewan peliharaan.<\\/li><li><strong>Pembatasan Tanggung Jawab:<\\/strong> Pihak manajemen tidak bertanggung jawab atas kehilangan atau kerusakan barang pribadi, serta cedera fisik yang disebabkan oleh kelalaian pengunjung.<\\/li><li><strong>Hak Manajemen:<\\/strong> Pihak pengelola berhak menolak masuk atau mengeluarkan pengunjung yang melanggar tata tertib tanpa kewajiban memberikan ganti rugi.<\\/li><\\/ul>"}', 2, '2026-07-22 15:00:32', '2026-07-22 15:00:32'),
