(34, 'App\\Models\\TicketPackage', 14, 'updated', '{"id":14,"name":"Unlimited Annual Pass","description":"Akses tak terbatas selama 12 bulan penuh + 1 handuk gratis per kunjungan + 20% off untuk tambahan 4 teman per kunjungan + 10% off gazebo, locker & merchandise. Dewasa: Rp 780.000, Anak (2-11 th): Rp 660.000.","price":"780000.00","discount_price":null,"type":"bundle","is_active":true,"created_by":null,"updated_by":null,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":null,"name_en":"Unlimited Annual Pass","description_en":"Unlimited 12-month access + 1 free towel per visit + 20% off for up to 4 friends per visit + 10% off gazebo, locker & merchandise. Adult: Rp 780,000, Child: Rp 660,000.","terms_and_conditions_en":null,"image_url":"https:\\/\\/picsum.photos\\/600\\/400?random=54","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null}', '{"updated_by":2,"image_url":"01M1DDXS1Y6CRRCJEZV9G6NVQ2.jpg"}', 2, '2026-09-01 02:49:12', '2026-09-01 02:49:12'),
(35, 'App\\Models\\TicketPackage', 15, 'updated', '{"id":15,"name":"Return Day Pass","description":"Hemat lebih dari 15% untuk kunjungan kedua Anda dalam 7 hari! Hanya bisa dibeli di loket dalam taman. Dewasa: Rp 63.000, Anak (2-11 th): Rp 50.000.","price":"63000.00","discount_price":null,"type":"bundle","is_active":true,"created_by":null,"updated_by":null,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":null,"name_en":"Return Day Pass","description_en":"Save over 15% on your second visit within 7 days! Only available for purchase inside the park. Adult: Rp 63,000, Child: Rp 50,000.","terms_and_conditions_en":null,"image_url":"https:\\/\\/picsum.photos\\/600\\/400?random=55","inquiry_type":"none","inquiry_custom_link":null,"sales_start":null,"sales_end":null}', '{"updated_by":2,"image_url":"01M1DEA6DFC156K6G7J7H3CQJ9.jpeg"}', 2, '2026-09-01 02:55:58', '2026-09-01 02:55:58'),
(36, 'App\\Models\\TicketPackage', 16, 'updated', '{"id":16,"name":"Custom Group Package","description":"Paket rombongan perusahaan, gathering tim, atau kunjungan sekolah\\/keluarga besar di atas 20 orang. Bisa kustom makanan, area eksklusif, & dedicated event coordinator.","price":"0.00","discount_price":null,"type":"bundle","is_active":true,"created_by":null,"updated_by":null,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":null,"name_en":"Custom Group Package","description_en":"Corporate gatherings, team events, or school\\/family trips of 20+ people. Custom meals, exclusive area reservations, & dedicated event coordinator available.","terms_and_conditions_en":null,"image_url":"https:\\/\\/picsum.photos\\/600\\/400?random=56","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null}', '{"updated_by":2,"image_url":"01M1DEBS30X0QPPYNH9Q65D3AQ.jpg"}', 2, '2026-09-01 02:56:50', '2026-09-01 02:56:50'),
(182, 'App\\Models\\User', 3, 'updated', '{"id":3,"name":"Fadli (Super Admin)","email":"superadmin@aquaboom.com","email_verified_at":null,"password":"$2y$12$eq3KU9WX2bUIWf530Mgc6uvwbTR20YVNZyy06fj8rN6NbBVG3b05W","remember_token":"xJGrMsnhgoMTQU9tILhVwCCvBIUyLAvxqALdjKGB044TDUz3OeaakuMDS7RG","role":"super_admin","deleted_at":null,"pin":null,"avatar_url":null,"permissions":null}', '{"remember_token":"5mxXIKJRqLzKQaE0djgmEC6iLSqeei3z1VswDJ1EOzRzQO87V5dotMNJ5jdw"}', 3, '2026-09-10 13:53:47', '2026-09-10 13:53:47'),
(37, 'App\\Models\\Facility', 8, 'updated', '{"id":8,"name":"GAZEBO PRIBADI & CABANA","type":"gazebo","description":"Tingkatkan kenyamanan kunjungan Anda dengan menyewa Gazebo pribadi. Terletak di area teduh nan asri, lengkap dengan layanan pesan antar makanan, pengisian daya, dan privasi penuh.","features":["Layanan makanan & minuman langsung ke gazebo","Privasi & kenyamanan maksimal","Kapasitas 4\\u20138 orang per gazebo"],"image_url":"https:\\/\\/picsum.photos\\/600\\/400?random=40","is_active":true,"name_en":"PRIVATE GAZEBO & CABANA","description_en":"Enhance your visit comfort by renting a private Gazebo. Located in a shady, lush area, complete with food delivery service, charging outlets, and full privacy.","features_en":["Food & beverage service directly to the gazebo","Maximum privacy & comfort","Capacity of 4\\u20138 people per gazebo"],"menu_items":null}', '{"image_url":"01M1DEVGEV48KF080FZVV3G6YH.jpeg"}', 2, '2026-09-01 03:05:26', '2026-09-01 03:05:26'),
(38, 'App\\Models\\Facility', 9, 'updated', '{"id":9,"name":"PENYEWAAN LOKER & HANDUK","type":"general","description":"Nikmati petualangan air tanpa rasa cemas. Kami menyediakan fasilitas loker otomatis dengan keamanan terintegrasi, serta penyewaan handuk bersih yang selalu disterilkan secara berkala.","features":["Sistem kunci loker menggunakan gelang RFID \\/ pin","Handuk premium bersih & higienis","Lokasi loker strategis dekat ruang bilas"],"image_url":"https:\\/\\/picsum.photos\\/600\\/400?random=42","is_active":true,"name_en":"LOCKER & TOWEL RENTAL","description_en":"Enjoy water adventures without worries. We provide automated locker facilities with integrated security, and clean towels sterilized regularly.","features_en":["Locker locking system using RFID wristband \\/ pin","Premium, clean & hygienic towels","Strategic locker locations near the shower rooms"],"menu_items":null}', '{"image_url":"01M1DEW1F95MX8X6NA2YJ89FJ7.jpg"}', 2, '2026-09-01 03:05:43', '2026-09-01 03:05:43'),
(39, 'App\\Models\\Facility', 10, 'updated', '{"id":10,"name":"RUANG BILAS & RUANG GANTI","type":"general","description":"Ruang bilas dan ruang ganti premium kami dirancang dengan mengutamakan kebersihan dan kenyamanan. Dilengkapi dengan pancuran air hangat, bilik ganti pribadi yang luas, serta pengering rambut.","features":["Bilik shower pribadi dengan air hangat","Peralatan mandi lengkap (sabun & sampo cair)","Wastafel dan cermin rias berukuran besar"],"image_url":"https:\\/\\/picsum.photos\\/600\\/400?random=44","is_active":true,"name_en":"SHOWER & CHANGING ROOMS","description_en":"Our premium shower and changing rooms are designed with hygiene and comfort in mind. Equipped with hot showers, spacious private changing stalls, and hair dryers.","features_en":["Private shower stalls with hot water","Complete toiletries (liquid soap & shampoo)","Large washbasin and vanity mirrors"],"menu_items":null}', '{"image_url":"01M1DEWGPZ7B2AYR5KEEF7SDFJ.jpeg"}', 2, '2026-09-01 03:05:59', '2026-09-01 03:05:59'),
(40, 'App\\Models\\Facility', 11, 'updated', '{"id":11,"name":"KLINIK PERTOLONGAN PERTAMA (P3K)","type":"general","description":"Keselamatan Anda adalah prioritas utama kami. Klinik P3K Aquaboom dilengkapi dengan peralatan medis darurat standar internasional serta dipandu oleh tim medis terlatih yang bersertifikasi.","features":["Perawat dan pertolongan medis siaga selama jam operasional","Obat-obatan umum dan peralatan bantuan darurat lengkap","Akses jalur evakuasi darurat yang cepat"],"image_url":"https:\\/\\/picsum.photos\\/600\\/400?random=46","is_active":true,"name_en":"FIRST AID CLINIC","description_en":"Your safety is our top priority. Aquaboom\'s First Aid Clinic is equipped with standard international emergency medical supplies and guided by certified trained medical staff.","features_en":["Nurses and medical assistance standby during operating hours","General medicines and complete emergency aid equipment","Fast emergency evacuation access route"],"menu_items":null}', '{"image_url":"01M1DEWVS96VDCABYMCDPHQTKH.jpg"}', 2, '2026-09-01 03:06:10', '2026-09-01 03:06:10'),
(41, 'App\\Models\\Facility', 12, 'updated', '{"id":12,"name":"MUSHOLA","type":"general","description":"Kami menyediakan ruang ibadah (Mushola) yang tenang, sejuk, dan bersih untuk menunjang kenyamanan ibadah Anda. Terpisah secara higienis antara area wudhu pria dan wanita.","features":["Tempat wudhu bersih terpisah gender","Dilengkapi sajadah, mukena, sarung, dan Al-Quran","Ruangan ber-AC yang nyaman"],"image_url":"https:\\/\\/picsum.photos\\/600\\/400?random=48","is_active":true,"name_en":"PRAYER ROOM (MUSHOLA)","description_en":"We provide a quiet, cool, and clean prayer room (Mushola) for your worship comfort. Hygienically separated ablution areas for men and women.","features_en":["Clean gender-segregated ablution areas","Equipped with prayer mats, female prayer robes, sarongs, and Al-Quran","Comfortable air-conditioned room"],"menu_items":null}', '{"image_url":"01M1DEXEYBNJP6XWJ7VMEB49W4.jpg"}', 2, '2026-09-01 03:06:30', '2026-09-01 03:06:30'),
