(91, 'App\\Models\\TicketPackage', 19, 'created', NULL, '{"id":19,"name":"Paket School Field Trip & Edu-Tour","name_en":"School Field Trip & Edu-Tour Package","description":"Paket rekreasi edukatif untuk siswa PAUD, TK, SD, SMP, SMA, dan universitas. Mengedepankan keselamatan maksimal dengan edukasi renang aman dan pengawasan intensif tim lifeguard bersertifikat.","description_en":"Educational fun water trip for preschool, elementary, junior\\/senior high, and university students. Focuses on water safety and certified lifeguard supervision.","terms_and_conditions":"\\u2022 Minimum pemesanan 15 siswa.\\n\\u2022 Gratis tiket masuk untuk guru \\/ pembina pendamping.\\n\\u2022 Sesi edukasi keselamatan air (water safety briefing).\\n\\u2022 Pengawasan penuh oleh tim lifeguard bersertifikat.","terms_and_conditions_en":"\\u2022 Minimum 15 students.\\n\\u2022 Free admission for accompanying teachers.\\n\\u2022 Water safety briefing session.\\n\\u2022 Certified lifeguard supervision.","price":75000,"discount_price":null,"discount_type":"amount","type":"gathering","image_url":"assets\\/img\\/gathering-school.jpg","inquiry_type":"whatsapp","is_active":true,"is_featured_home":false,"validity_type":"all_days"}', NULL, '2026-09-02 06:53:08', '2026-09-02 06:53:08'),
