(94, 'App\\Models\\TicketPackage', 17, 'updated', '{"id":17,"name":"Paket Corporate Gathering & Outing","description":"Tingkatkan kekompakan dan sinergi tim kerja dengan program ice breaking water games seru, pemandu games profesional, panggung sambutan, sound system nirkabel, dan sajian buffet lezat di venue rooftop prestisius.","price":"150000.00","discount_price":null,"type":"gathering","is_active":true,"created_by":null,"updated_by":null,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":"\\u2022 Minimum pemesanan 10 orang\\/pax.\\n\\u2022 Sudah termasuk tiket all-access seluruh wahana.\\n\\u2022 Fasilitas sound system nirkabel & mikrofon.\\n\\u2022 Area gazebo privat rombongan.\\n\\u2022 Paket konsumsi buffet \\/ lunch box dapat disesuaikan.","name_en":"Corporate Gathering & Outing Package","description_en":"Boost team synergy with fun team building ice breaking water games, professional MC, private gazebo, sound system, and lunch buffet at our rooftop venue.","terms_and_conditions_en":"\\u2022 Minimum 10 pax.\\n\\u2022 Includes all-access waterpark admission.\\n\\u2022 Wireless sound system & mic.\\n\\u2022 Private group gazebo.\\n\\u2022 Customizable buffet\\/lunch box menu.","image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/assets\\/img\\/gathering-corporate.jpg","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null,"is_featured_home":true}', '{"price":null,"updated_by":2}', 2, '2026-09-02 06:59:58', '2026-09-02 06:59:58'),
