(95, 'App\\Models\\TicketPackage', 18, 'updated', '{"id":18,"name":"Paket Family Gathering & Arisan","description":"Ciptakan momen kebersamaan hangat bersama keluarga besar, reuni sekolah, atau arisan komunitas. Tersedia gazebo santai, kolam dangkal aman untuk balita, kolam arus santai, dan seluncuran seru untuk dewasa.","price":"120000.00","discount_price":null,"type":"gathering","is_active":true,"created_by":null,"updated_by":null,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":"\\u2022 Minimum pemesanan 10 orang\\/pax.\\n\\u2022 Sudah termasuk tiket all-access seluruh wahana.\\n\\u2022 Complimentary sewa gazebo eksklusif.\\n\\u2022 Free sewa ban pelampung.\\n\\u2022 Diskon khusus rombongan keluarga.","name_en":"Family Gathering & Reunion Package","description_en":"Create warm memories with big family, school reunion, or community gathering. Includes relaxed gazebo, shallow kids pool, lazy river, and slides.","terms_and_conditions_en":"\\u2022 Minimum 10 pax.\\n\\u2022 Includes all-access waterpark admission.\\n\\u2022 Complimentary exclusive gazebo.\\n\\u2022 Free swimming tube \\/ floats.\\n\\u2022 Special family group discount.","image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/assets\\/img\\/gathering-family.jpg","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null,"is_featured_home":true}', '{"price":null,"updated_by":2}', 2, '2026-09-02 07:00:10', '2026-09-02 07:00:10'),
(96, 'App\\Models\\TicketPackage', 19, 'updated', '{"id":19,"name":"Paket School Field Trip & Edu-Tour","description":"Paket rekreasi edukatif untuk siswa PAUD, TK, SD, SMP, SMA, dan universitas. Mengedepankan keselamatan maksimal dengan edukasi renang aman dan pengawasan intensif tim lifeguard bersertifikat.","price":"75000.00","discount_price":null,"type":"gathering","is_active":true,"created_by":null,"updated_by":null,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":"\\u2022 Minimum pemesanan 15 siswa.\\n\\u2022 Gratis tiket masuk untuk guru \\/ pembina pendamping.\\n\\u2022 Sesi edukasi keselamatan air (water safety briefing).\\n\\u2022 Pengawasan penuh oleh tim lifeguard bersertifikat.","name_en":"School Field Trip & Edu-Tour Package","description_en":"Educational fun water trip for preschool, elementary, junior\\/senior high, and university students. Focuses on water safety and certified lifeguard supervision.","terms_and_conditions_en":"\\u2022 Minimum 15 students.\\n\\u2022 Free admission for accompanying teachers.\\n\\u2022 Water safety briefing session.\\n\\u2022 Certified lifeguard supervision.","image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/assets\\/img\\/gathering-school.jpg","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null,"is_featured_home":false}', '{"price":null,"updated_by":2}', 2, '2026-09-02 07:00:20', '2026-09-02 07:00:20'),
