(113, 'App\\Models\\Facility', 9, 'updated', '{"id":9,"name":"PENYEWAAN LOKER & HANDUK","type":"general","description":"Nikmati petualangan air tanpa rasa cemas. Kami menyediakan fasilitas loker otomatis dengan keamanan terintegrasi, serta penyewaan handuk bersih yang selalu disterilkan secara berkala.","features":["Sistem kunci loker menggunakan gelang RFID \\/ pin","Handuk premium bersih & higienis","Lokasi loker strategis dekat ruang bilas"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/01M1DEW1F95MX8X6NA2YJ89FJ7.jpg","is_active":true,"name_en":"LOCKER & TOWEL RENTAL","description_en":"Enjoy water adventures without worries. We provide automated locker facilities with integrated security, and clean towels sterilized regularly.","features_en":["Locker locking system using RFID wristband \\/ pin","Premium, clean & hygienic towels","Strategic locker locations near the shower rooms"],"menu_items":null}', '{"image_url":"facilities\\/01M1JM6WRC8RBWJF6KWJD69A4W.jpg"}', 2, '2026-09-03 03:15:14', '2026-09-03 03:15:14'),
(114, 'App\\Models\\Facility', 11, 'updated', '{"id":11,"name":"KLINIK PERTOLONGAN PERTAMA (P3K)","type":"general","description":"Keselamatan Anda adalah prioritas utama kami. Klinik P3K Aquaboom dilengkapi dengan peralatan medis darurat standar internasional serta dipandu oleh tim medis terlatih yang bersertifikasi.","features":["Perawat dan pertolongan medis siaga selama jam operasional","Obat-obatan umum dan peralatan bantuan darurat lengkap","Akses jalur evakuasi darurat yang cepat"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/01M1DEWVS96VDCABYMCDPHQTKH.jpg","is_active":true,"name_en":"FIRST AID CLINIC","description_en":"Your safety is our top priority. Aquaboom\'s First Aid Clinic is equipped with standard international emergency medical supplies and guided by certified trained medical staff.","features_en":["Nurses and medical assistance standby during operating hours","General medicines and complete emergency aid equipment","Fast emergency evacuation access route"],"menu_items":null}', '{"image_url":"facilities\\/01M1JMHS18R35SCQCSEYR1ZT7D.jpg"}', 2, '2026-09-03 03:21:10', '2026-09-03 03:21:10'),
(115, 'App\\Models\\TicketPackage', 13, 'updated', '{"id":13,"name":"Paket Birthday & Private Pool Party","description":"Pesta ulang tahun impian di tepi kolam renang rooftop dengan pemandangan kota. Dilengkapi dekorasi balon warna-warni, paket kids meal, pemutaran lagu ulang tahun, dan spot foto yang Instagrammable.","price":null,"discount_price":null,"type":"gathering","is_active":true,"created_by":null,"updated_by":2,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":"\\u2022 Paket berlaku untuk 10 orang anak + pendamping.\\n\\u2022 Dekorasi tematik poolside & backdrop ulang tahun.\\n\\u2022 Sound system pemutaran lagu ulang tahun & mic.\\n\\u2022 Paket kids meal lezat + goodie bag area.","name_en":"Birthday & Private Pool Party Package","description_en":"Dream rooftop poolside birthday party with city views. Features colorful balloon setup, kids meal, birthday song sound system, and photo spot.","terms_and_conditions_en":"\\u2022 Package for 10 kids + chaperones.\\n\\u2022 Thematic poolside backdrop & balloon arch.\\n\\u2022 Birthday sound system & mic.\\n\\u2022 Kids meals + goodie bag spot.","image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/assets\\/img\\/gathering-birthday.jpg","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null,"is_featured_home":true,"sort_order":13}', '{"image_url":"packages\\/01M1JN7F5J9FPZEXDX9HJGE72P.jpeg"}', 2, '2026-09-03 03:33:01', '2026-09-03 03:33:01'),
