(140, 'App\\Models\\Facility', 10, 'updated', '{"id":10,"name":"RUANG BILAS & RUANG GANTI","type":"general","description":"Ruang bilas dan ruang ganti premium kami dirancang dengan mengutamakan kebersihan dan kenyamanan. Dilengkapi dengan pancuran air hangat, bilik ganti pribadi yang luas, serta pengering rambut.","features":["Bilik shower pribadi dengan air hangat","Peralatan mandi lengkap (sabun & sampo cair)","Wastafel dan cermin rias berukuran besar"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/01M1DEWGPZ7B2AYR5KEEF7SDFJ.jpeg","is_active":true,"name_en":"SHOWER & CHANGING ROOMS","description_en":"Our premium shower and changing rooms are designed with hygiene and comfort in mind. Equipped with hot showers, spacious private changing stalls, and hair dryers.","features_en":["Private shower stalls with hot water","Complete toiletries (liquid soap & shampoo)","Large washbasin and vanity mirrors"],"menu_items":null,"sort_order":3}', '{"image_url":"facilities\\/01M1SB2HMRBV7NZ1P6ZCN5CY07.jpeg"}', 2, '2026-09-05 17:50:15', '2026-09-05 17:50:15'),
(141, 'App\\Models\\Facility', 9, 'updated', '{"id":9,"name":"PENYEWAAN LOKER & HANDUK","type":"general","description":"Nikmati petualangan air tanpa rasa cemas. Kami menyediakan fasilitas loker otomatis dengan keamanan terintegrasi, serta penyewaan handuk bersih yang selalu disterilkan secara berkala.","features":["Handuk premium bersih & higienis","Lokasi loker strategis dekat ruang bilas","sistem kunci loker"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/facilities\\/01M1JM6WRC8RBWJF6KWJD69A4W.jpg","is_active":true,"name_en":"LOCKER & TOWEL RENTAL","description_en":"Enjoy water adventures without worries. We provide automated locker facilities with integrated security, and clean towels sterilized regularly.","features_en":["Premium, clean & hygienic towels","Strategic locker locations near the shower rooms","Locker Locking System"],"menu_items":null,"sort_order":1}', '{"image_url":"facilities\\/01M1SB3DEEVBGVXKAKBQ0YK990.jpeg"}', 2, '2026-09-05 17:50:44', '2026-09-05 17:50:44');
