(143, 'App\\Models\\TicketPackage', 14, 'updated', '{"id":14,"name":"Unlimited Annual Pass","description":"Akses tak terbatas selama 12 bulan penuh + 1 handuk gratis per kunjungan + 20% off untuk tambahan 4 teman per kunjungan + 10% off gazebo, locker & merchandise. Dewasa: Rp 780.000, Anak (2-11 th): Rp 660.000.","price":null,"discount_price":null,"type":"bundle","is_active":true,"created_by":null,"updated_by":2,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":null,"name_en":"Unlimited Annual Pass","description_en":"Unlimited 12-month access + 1 free towel per visit + 20% off for up to 4 friends per visit + 10% off gazebo, locker & merchandise. Adult: Rp 780,000, Child: Rp 660,000.","terms_and_conditions_en":null,"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/01M1E0ABZCN3PP138QXT71QVSQ.jpg","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null,"is_featured_home":false,"sort_order":14}', '{"description":"<ul><li>Akses tak terbatas selama 12 bulan penuh +&nbsp;<\\/li><li>1 handuk gratis per kunjungan +<\\/li><li>&nbsp;20% off untuk tambahan 4 teman per kunjungan +&nbsp;<\\/li><li>10% off gazebo, locker &amp; merchandise. Dewasa: Rp 780.000, Anak (2-11 th): Rp 660.000.<\\/li><\\/ul>","description_en":"<ul><li>Unlimited access for the full 12 months +&nbsp;<\\/li><li>1 free towel per visit +<\\/li><li>&nbsp;20% off for an additional 4 friends per visit +&nbsp;<\\/li><li>10% off gazebos, lockers &amp; merchandise. Adults: IDR 780,000, Children (2-11 yrs): IDR 660,000.<\\/li><\\/ul>"}', 2, '2026-09-08 10:00:53', '2026-09-08 10:00:53'),
