(174, 'App\\Models\\Facility', 9, 'updated', '{"id":9,"name":"PENYEWAAN LOKER & HANDUK","type":"general","description":"Nikmati petualangan air tanpa rasa cemas. Kami menyediakan fasilitas loker otomatis dengan keamanan terintegrasi, serta penyewaan handuk bersih yang selalu disterilkan secara berkala.","features":["Handuk premium bersih & higienis","Lokasi loker strategis dekat ruang bilas","sistem kunci loker"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/facilities\\/01M24KWC1836C7NDDZSMS2FNTP.jpg","is_active":true,"name_en":"LOCKER & TOWEL RENTAL","description_en":"Enjoy water adventures without worries. We provide automated locker facilities with integrated security, and clean towels sterilized regularly.","features_en":["Premium, clean & hygienic towels","Strategic locker locations near the shower rooms","Locker Locking System"],"menu_items":null,"sort_order":1}', '{"image_url":"facilities\\/01M24Y0ED83TVHV0P5RB5ZQMAM.jpeg"}', 3, '2026-09-10 12:52:48', '2026-09-10 12:52:48'),
(175, 'App\\Models\\Facility', 12, 'updated', '{"id":12,"name":"MUSHOLA","type":"general","description":"Kami menyediakan ruang ibadah (Mushola) yang tenang, sejuk, dan bersih untuk menunjang kenyamanan ibadah Anda. Terpisah secara higienis antara area wudhu pria dan wanita.","features":["Tempat wudhu bersih terpisah gender","Dilengkapi sajadah, mukena, sarung, dan Al-Quran","Ruangan ber-AC yang nyaman"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/facilities\\/01M24H4MT0FM145H16B13SAMKT.png","is_active":true,"name_en":"PRAYER ROOM (MUSHOLA)","description_en":"We provide a quiet, cool, and clean prayer room (Mushola) for your worship comfort. Hygienically separated ablution areas for men and women.","features_en":["Clean gender-segregated ablution areas","Equipped with prayer mats, female prayer robes, sarongs, and Al-Quran","Comfortable air-conditioned room"],"menu_items":null,"sort_order":5}', '{"image_url":"facilities\\/01M24ZCBAA4GCRHWMCG2TBHC5C.png"}', 3, '2026-09-10 13:16:47', '2026-09-10 13:16:47'),
