(362, 'App\\Models\\Wahana', 4, 'updated', '{"id":4,"name":"Area Bermain Air Keluarga","description":"Wahana permainan air keluarga yang aman dan menyenangkan untuk anak-anak hingga dewasa.","image_url":"https:\\/\\/aquaboombsb.com\\/wp-content\\/uploads\\/2023\\/12\\/V1.jpg","order_column":1,"created_by":null,"updated_by":3,"deleted_at":null,"thrill_level":"Family","name_en":"Family Water Playground","description_en":"Safe and fun family water play ride for children to adults."}', '{"image_url":"wahanas\\/01M2Q5CKN9DGKVT2QKFP787EYW.jpeg"}', 3, '2026-09-17 15:48:06', '2026-09-17 15:48:06'),
(196, 'App\\Models\\Facility', 8, 'updated', '{"id":8,"name":"GAZEBO PRIBADI & CABANA","type":"gazebo","description":"Tingkatkan kenyamanan kunjungan Anda dengan menyewa Gazebo pribadi. Terletak di area teduh nan asri, lengkap dengan layanan pesan antar makanan, pengisian daya, dan privasi penuh.","features":["Layanan makanan & minuman langsung ke gazebo","Privasi & kenyamanan maksimal","kapasitas 4-6 orang per gazebo"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/facilities\\/01M1JM6B2N85WQ144FSF8H4VEZ.jpeg","is_active":true,"name_en":"PRIVATE GAZEBO & CABANA","description_en":"Enhance your visit comfort by renting a private Gazebo. Located in a shady, lush area, complete with food delivery service, charging outlets, and full privacy.","features_en":["Food & beverage service directly to the gazebo","Maximum privacy & comfort","Capacity of 4-6 people on gazebo"],"menu_items":null,"sort_order":2}', '{"image_url":"facilities\\/01M253EP3QMK88P5FZEGNRMYQN.jpeg"}', 3, '2026-09-10 14:27:58', '2026-09-10 14:27:58'),
(197, 'App\\Models\\Facility', 10, 'updated', '{"id":10,"name":"RUANG BILAS & RUANG GANTI","type":"general","description":"Ruang bilas dan ruang ganti premium kami dirancang dengan mengutamakan kebersihan dan kenyamanan. Dilengkapi dengan pancuran air hangat, bilik ganti pribadi yang luas, serta pengering rambut.","features":["Bilik shower pribadi dengan air hangat","Peralatan mandi lengkap (sabun & sampo cair)","Wastafel dan cermin rias berukuran besar"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/facilities\\/01M24H5ZNY31PAV9T2ZJEN72XA.jpeg","is_active":true,"name_en":"SHOWER & CHANGING ROOMS","description_en":"Our premium shower and changing rooms are designed with hygiene and comfort in mind. Equipped with hot showers, spacious private changing stalls, and hair dryers.","features_en":["Private shower stalls with hot water","Complete toiletries (liquid soap & shampoo)","Large washbasin and vanity mirrors"],"menu_items":null,"sort_order":3}', '{"image_url":"facilities\\/01M253XB6V7Q8HM17JEY3A44QG.jpeg"}', 3, '2026-09-10 14:35:58', '2026-09-10 14:35:58'),
(198, 'App\\Models\\AddOn', 5, 'updated', '{"id":5,"name":"Sewa Gazebo Standard","description":"Gazebo nyaman kapasitas 4-6 orang untuk bersantai bersama keluarga, include stopkontak dan matras empuk.","price":"150000.00","image":"addons\\/01M1JX0V6WHNPVSDXQJ2855H0J.jpeg","is_active":true,"deleted_at":null,"name_en":null,"description_en":"<p>Comfortable gazebo with a capacity of 4-6 people to relax with family, including outlet and soft mattress.<\\/p>","sort_order":5}', '{"image":"addons\\/01M2545SRFCYWBSJVH3A36S6SM.jpeg"}', 3, '2026-09-10 14:40:35', '2026-09-10 14:40:35'),
(199, 'App\\Models\\Facility', 12, 'updated', '{"id":12,"name":"MUSHOLA","type":"general","description":"Kami menyediakan ruang ibadah (Mushola) yang tenang, sejuk, dan bersih untuk menunjang kenyamanan ibadah Anda. Terpisah secara higienis antara area wudhu pria dan wanita.","features":["Tempat wudhu bersih terpisah gender","Dilengkapi sajadah, mukena, sarung, dan Al-Quran","Ruangan ber-AC yang nyaman"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/facilities\\/01M24ZCBAA4GCRHWMCG2TBHC5C.png","is_active":true,"name_en":"PRAYER ROOM (MUSHOLA)","description_en":"We provide a quiet, cool, and clean prayer room (Mushola) for your worship comfort. Hygienically separated ablution areas for men and women.","features_en":["Clean gender-segregated ablution areas","Equipped with prayer mats, female prayer robes, sarongs, and Al-Quran","Comfortable air-conditioned room"],"menu_items":null,"sort_order":5}', '{"image_url":"facilities\\/01M2546TJVD2B6N4YNQ0JRMY7A.jpeg"}', 3, '2026-09-10 14:41:09', '2026-09-10 14:41:09'),
