(242, 'App\\Models\\Setting', 21, 'updated', '{"id":21,"key":"hero_description","value":"Aquaboom Waterpark Balikpapan \\u2014 Satu-satunya Waterpark yang berada di atas gedung bertingkat di Indonesia. Managed by Astara Hotel Balikpapan.","group":"homepage","type":"text"}', '{"value":"Aquaboom Waterpark Balikpapan \\u2014 Waterpark ikonik di Balikpapan yang berada di 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan. Managed by Astara Hotel Balikpapan."}', NULL, '2026-09-11 09:31:52', '2026-09-11 09:31:52'),
(243, 'App\\Models\\Setting', 22, 'updated', '{"id":22,"key":"hero_description_en","value":"Aquaboom Waterpark Balikpapan \\u2014 The only waterpark located on top of a high-rise building in Indonesia. Managed by Astara Hotel Balikpapan.","group":"homepage","type":"text"}', '{"value":"Aquaboom Waterpark Balikpapan \\u2014 Balikpapan\'s iconic waterpark located on 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan. Managed by Astara Hotel Balikpapan."}', NULL, '2026-09-11 09:31:52', '2026-09-11 09:31:52'),
(244, 'App\\Models\\Setting', 23, 'updated', '{"id":23,"key":"philosophy_text","value":"Aquaboom Waterpark Balikpapan menghadirkan pengalaman rekreasi air urban yang unik. Berlokasi strategis di pusat kota Balikpapan (BSB Area), kami menawarkan keceriaan wahana air premium di atap gedung dengan pemandangan kota yang menakjubkan.","group":"about","type":"text"}', '{"value":"Aquaboom Waterpark Balikpapan menghadirkan pengalaman rekreasi air urban yang unik di Balikpapan. Berlokasi strategis di pusat kota Balikpapan (BSB Area), kami menawarkan keceriaan wahana air premium di 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan."}', NULL, '2026-09-11 09:31:52', '2026-09-11 09:31:52'),
(245, 'App\\Models\\Setting', 24, 'updated', '{"id":24,"key":"philosophy_text_en","value":"Aquaboom Waterpark Balikpapan brings a unique urban water recreation experience. Strategically located in the heart of Balikpapan (BSB Area), we offer the joy of premium water slides on the rooftop with a stunning city view.","group":"about","type":"text"}', '{"value":"Aquaboom Waterpark Balikpapan brings a unique urban water recreation experience in Balikpapan. Strategically located in the heart of Balikpapan (BSB Area), we offer the joy of premium water slides on 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan."}', NULL, '2026-09-11 09:31:52', '2026-09-11 09:31:52');
