(246, 'App\\Models\\Setting', 27, 'updated', '{"id":27,"key":"mission_text","value":"Terletak di Lantai 7 Astara Hotel - Balikpapan Superblock, Aquaboom menghadirkan standar baru rekreasi air perkotaan. Kami menggabungkan keseruan bermain air berkelas dengan aksesibilitas dan kenyamanan modern.","group":"about","type":"text"}', '{"value":"Terletak di Lantai 7 (Shared Common Area Astara Hotel & Pentacity Hotel Balikpapan) - Balikpapan Superblock, Aquaboom menghadirkan standar baru rekreasi air perkotaan di Balikpapan. Kami menggabungkan keseruan bermain air berkelas dengan aksesibilitas dan kenyamanan modern."}', NULL, '2026-09-11 09:31:52', '2026-09-11 09:31:52'),
(247, 'App\\Models\\Setting', 28, 'updated', '{"id":28,"key":"mission_text_en","value":"Located on the 7th Floor of Astara Hotel - Balikpapan Superblock, Aquaboom presents a new standard of urban water recreation. We combine the excitement of high-class water play with accessibility and modern comfort.","group":"about","type":"text"}', '{"value":"Located on the 7th Floor (Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan) - Balikpapan Superblock, Aquaboom presents a new standard of urban water recreation in Balikpapan. We combine the excitement of high-class water play with accessibility and modern comfort."}', NULL, '2026-09-11 09:31:52', '2026-09-11 09:31:52'),
