(292, 'App\\Models\\Wahana', 6, 'updated', '{"id":6,"name":"Family Water Playground","description":"Wahana permainan air keluarga yang aman dan menyenangkan untuk anak-anak hingga dewasa.","image_url":"https:\\/\\/aquaboombsb.com\\/wp-content\\/uploads\\/2023\\/12\\/V3.jpg","order_column":3,"created_by":null,"updated_by":null,"deleted_at":null,"thrill_level":null,"name_en":"Family Water Playground","description_en":"Safe and fun family water play ride for children to adults."}', '{"name":"Pusaran Tornado","description":"Pacu adrenalin meluncur vertikal menuju corong tornado raksasa dan rasakan sensasi terombang-ambing melawan gravitasi sebelum terjun ke kolam.","updated_by":3,"thrill_level":"Thrill","name_en":"Tornado Slide","description_en":"Feel the ultimate adrenaline rush as you plunge into a massive tornado funnel, oscillating against gravity before splashing into the landing pool."}', 3, '2026-09-14 09:13:36', '2026-09-14 09:13:36'),
(293, 'App\\Models\\Wahana', 5, 'updated', '{"id":5,"name":"Splash & Leisure Pool","description":"Nikmati sensasi berenang santai yang menyenangkan di 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan dengan pemandangan kota Balikpapan.","image_url":"https:\\/\\/aquaboombsb.com\\/wp-content\\/uploads\\/2023\\/12\\/V2.jpg","order_column":2,"created_by":null,"updated_by":null,"deleted_at":null,"thrill_level":null,"name_en":"Splash & Leisure Pool","description_en":"Enjoy the sensation of relaxing swimming on 7F - Shared Common Area for Astara Hotel & Pentacity Hotel Balikpapan with Balikpapan city views."}', '{"name":"Seluncuran Spiral","description":"Rasakan sensasi meluncur cepat melintasi liukan spiral bertingkat penuh warna sebelum mendarat segar di kolam utama.","updated_by":3,"thrill_level":"Fun","name_en":"Twister Spiral Slides","description_en":"Experience the rush of sliding down colorful, winding multi-level spiral chutes before making a refreshing splash into the main pool."}', 3, '2026-09-14 09:15:01', '2026-09-14 09:15:01'),
(294, 'App\\Models\\Facility', 7, 'updated', '{"id":7,"name":"Aquaboom Food","type":"dining","description":"Tempat menikmati aneka makanan ringan favorit, hidangan lezat khas lokal, dan minuman segar setelah bermain air.","features":["Menu variatif","Minuman dingin segar","Area bersih nyaman"],"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/01M1BBZSHH54HET029PKJQWQJG.webp","is_active":true,"name_en":"Aquaboom","description_en":"A place to enjoy various favorite snacks, delicious local dishes, and fresh drinks after playing in the water.","features_en":["Varied menu","Fresh cold drinks","Clean & comfortable area"],"menu_items":["dining-menus\\/01M1NSQ7T11HT594830GSDYWD5.jpeg","dining-menus\\/01M1NSQ7T2ND5Z9BEGPK7FRS7A.jpeg","dining-menus\\/01M1NTP96HBDAC66XX48VQ1G33.jpeg","dining-menus\\/01M2730CV67QY1FF642F5SZX1V.jpg"],"sort_order":7}', '{"name":"Aquaboom Kafe","description":"Tempat ideal untuk bersantai dan mengisi kembali energi setelah berenang. Menyajikan aneka camilan lezat, makanan favorit keluarga, serta pilihan minuman dingin yang menyegarkan.","image_url":"dining\\/01M2EVDAFR43XHY9DYC3P0W2XH.jpeg","name_en":"Aquaboom Cafe & Bites","description_en":"The perfect spot to unwind and recharge after swimming. Serving a variety of tasty snacks, family-favorite meals, and a refreshing selection of cold beverages."}', 3, '2026-09-14 09:19:49', '2026-09-14 09:19:49'),
(295, 'App\\Models\\TicketPackage', 14, 'updated', '{"id":14,"name":"Unlimited Annual Pass","description":"<ul><li>Akses tak terbatas selama 12 bulan penuh +&nbsp;<\\/li><li>1 handuk gratis per kunjungan +<\\/li><li>&nbsp;20% off untuk tambahan 4 teman per kunjungan +&nbsp;<\\/li><li>10% off gazebo, locker &amp; merchandise. Dewasa: Rp 780.000, Anak (2-11 th): Rp 660.000.<\\/li><\\/ul>","price":null,"discount_price":null,"type":"bundle","is_active":true,"created_by":null,"updated_by":2,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":null,"name_en":"Unlimited Annual Pass","description_en":"<ul><li>Unlimited access for the full 12 months +&nbsp;<\\/li><li>1 free towel per visit +<\\/li><li>&nbsp;20% off for an additional 4 friends per visit +&nbsp;<\\/li><li>10% off gazebos, lockers &amp; merchandise. Adults: IDR 780,000, Children (2-11 yrs): IDR 660,000.<\\/li><\\/ul>","terms_and_conditions_en":null,"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/01M1E0ABZCN3PP138QXT71QVSQ.jpg","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null,"is_featured_home":false,"sort_order":14}', '{"name":"Tiket Terusan Tahunan","updated_by":3}', 3, '2026-09-14 10:43:03', '2026-09-14 10:43:03'),
