(297, 'App\\Models\\TicketPackage', 16, 'updated', '{"id":16,"name":"Custom Group Package","description":"Paket rombongan perusahaan, gathering tim, atau kunjungan sekolah\\/keluarga besar di atas 20 orang. Bisa kustom makanan, area eksklusif, & dedicated event coordinator.","price":null,"discount_price":null,"type":"bundle","is_active":true,"created_by":null,"updated_by":2,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":null,"name_en":"Custom Group Package","description_en":"Corporate gatherings, team events, or school\\/family trips of 20+ people. Custom meals, exclusive area reservations, & dedicated event coordinator available.","terms_and_conditions_en":null,"image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/01M1DEBS30X0QPPYNH9Q65D3AQ.jpg","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null,"is_featured_home":false,"sort_order":16}', '{"name":"Paket Rombongan Kustom","updated_by":3}', 3, '2026-09-14 10:44:50', '2026-09-14 10:44:50'),
(298, 'App\\Models\\TicketPackage', 17, 'updated', '{"id":17,"name":"Paket Corporate Gathering & Outing","description":"Tingkatkan kekompakan dan sinergi tim kerja dengan program ice breaking water games seru, pemandu games profesional, panggung sambutan, sound system nirkabel, dan sajian buffet lezat di venue rooftop prestisius.","price":null,"discount_price":null,"type":"gathering","is_active":true,"created_by":null,"updated_by":2,"discount_type":"amount","deleted_at":null,"validity_type":"all_days","valid_dates":null,"valid_days":null,"terms_and_conditions":"\\u2022 Minimum pemesanan 10 orang\\/pax.\\n\\u2022 Sudah termasuk tiket all-access seluruh wahana.\\n\\u2022 Fasilitas sound system nirkabel & mikrofon.\\n\\u2022 Area gazebo privat rombongan.\\n\\u2022 Paket konsumsi buffet \\/ lunch box dapat disesuaikan.","name_en":"Corporate Gathering & Outing Package","description_en":"Boost team synergy with fun team building ice breaking water games, professional MC, private gazebo, sound system, and lunch buffet at our rooftop venue.","terms_and_conditions_en":"\\u2022 Minimum 10 pax.\\n\\u2022 Includes all-access waterpark admission.\\n\\u2022 Wireless sound system & mic.\\n\\u2022 Private group gazebo.\\n\\u2022 Customizable buffet\\/lunch box menu.","image_url":"https:\\/\\/aqb.jatrahotels.biz.id\\/uploads\\/packages\\/01M1JWK029WXVSBCP45TKNDZRG.jpeg","inquiry_type":"whatsapp","inquiry_custom_link":null,"sales_start":null,"sales_end":null,"is_featured_home":true,"sort_order":17}', '{"name":"Paket Gathering Perusahaan & Outing","updated_by":3}', 3, '2026-09-14 10:45:17', '2026-09-14 10:45:17');
